def c(id,text,ss,scope,reason,location,domainnotes,grade='Low'):
 # All Low judgments here concern clinical inference, not an automatic laboratory design score.
 claim={'claimId':'FENB-'+id,'statement':text,'scope':scope,'sourceIds':ss,'grade':grade,'rationale':reason,'locators':location,'readingDepth':{s:('abstract_only' if s==ids['36039738'] else 'targeted_full_text_inspection') for s in ss},'sourceBindings':[], 'domains':[], 'assessedAt':'2026-10-27','reviewState':'pending_independent_and_human_review'}
 for s in ss:
  obj=next((z for z in new+base['sources'] if z['id']==s),None); binding={'sourceId':s,'sourceObjectSha256':sha(obj)}
  pmid=next((p for p,si in ids.items() if si==s),obj.get('pmid','') if obj else '')
  raw=next((r for r in inputs['papers'] if r.get('pmid')==pmid or r.get('canonicalSourceId')==s or r.get('existingSourceId')==s),None)
  if not raw and s=='MECH-D10-MICROTUBULE-2018':raw=next(r for r in inputs['papers'] if r.get('pmid')=='30093705')
  if not raw and s.startswith('P-D10-LIVER'):raw=next((r for r in inputs['papers'] if r.get('sourceId')==s),None)
  if raw:binding.update({'fileSha256':raw['sha256'],'path':raw['path']})
  elif s in ['CTX-D10-FDA',ids['36039738']]:binding['webUrl']=obj['url']
  else:binding['bindingLimit']='Existing source object retained; see source-access receipt for original file binding.'
  claim['sourceBindings'].append(binding)
 for name,note in zip(['Study methods','Directness','Precision','Consistency','Source integrity'],domainnotes):claim['domains'].append({'domain':name,'judgment':note,'sourceIds':ss})
 claims.append(claim);return {'text':text,'sources':ss}
